1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.StringUtil;
4	import org.jsoup.nodes.Element;
5	
6	import java.util.Arrays;
7	
8	/**
9	 Parses and sanitizes the inline CSS of an element's {@code style} attribute, one declaration at a time. The parser is
10	 a small hand scanner rather than a full CSS parser: declarations are split on semicolons while tracking the actual
11	 nesting of strings, parentheses, block comments, and CSS backslash escapes, so that punctuation inside strings
12	 ({@code font-family: 'Calibri;'}) or functions ({@code background: url(/img;a.png)}) cannot break out of its
13	 declaration.
14	
15	 <p>Declarations with no recognizable property, an unclosed comment, an unclosed function or string (recovered only at
16	 a newline, per the CSS bad-string rule), unbalanced parentheses, or a forbidden or unverifiable external reference
17	 are dropped individually; surrounding safe declarations, other attributes, and the element's text are untouched.
18	 Each surviving declaration is scanned for references ({@code url(...)}, the legacy {@code expression(...)}
19	 function, and an {@code @import} at-rule) and every reference found is normalized through CSS unescaping and checked
20	 against the safelist's URL rules. Repeated separators and other degenerate input never throw and never cause
21	 following declarations to be joined into a rejected value.</p>
22	
23	 <p>The cleaner is stateless and thread-safe; all per-value state lives on the local parse stack.</p>
24	 */
25	final class StyleCleaner {
26	    private final Safelist safelist;
27	    private final String tagName;
28	    private final Element el;
29	
30	    private StyleCleaner(Safelist safelist, String tagName, Element el) {
31	        this.safelist = safelist;
32	        this.tagName = tagName;
33	        this.el = el;
34	    }
35	
36	    /**
37	     Cleans an inline {@code style} attribute value declaration by declaration, preserving the order and original
38	     text of every declaration that survives.
39	     @return the cleaned value, or {@code null} when no declaration survives (in which case the attribute is removed)
40	     */
41	    static String clean(Safelist safelist, String tagName, Element el, String value) {
42	        return new StyleCleaner(safelist, tagName, el).clean(value);
43	    }
44	
45	    private String clean(String value) {
46	        StringBuilder out = StringUtil.borrowBuilder();
47	        int length = value.length();
48	        int[] match = parenMatches(value); // index of each parenthesis's mate, or -1 when unmatched
49	        int[] opens = new int[length]; // positions of the currently open parentheses
50	        int segStart = 0;
51	        int parenDepth = 0;
52	        boolean segmentBad = false; // this segment already contains a malformed construct
53	        int i = 0;
54	        while (i < length) {
55	            char c = value.charAt(i);
56	            if (c == '\\') { // CSS escape: the next code unit is literal, even '\;' or '\"'
57	                i += 2;
58	                continue;
59	            }
60	            if (c == '"' || c == '\'') {
61	                int[] quote = scanQuoted(value, i + 1, c);
62	                if (quote[1] == 1) {
63	                    i = quote[0] + 1;
64	                } else {
65	                    segmentBad = true; // a bad-string token makes only this declaration malformed
66	                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
67	                }
68	                continue;
69	            }
70	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
71	                int close = value.indexOf("*/", i + 2);
72	                if (close < 0) { // an unterminated comment swallows the tail, which is never parsed as CSS
73	                    appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
74	                    segStart = length;
75	                    break;
76	                }
77	                i = close + 2;
78	                continue;
79	            }
80	            if (c == '(') {
81	                opens[parenDepth++] = i;
82	            } else if (c == ')') {
83	                if (parenDepth > 0) parenDepth--;
84	                else segmentBad = true; // a stray ')' makes this declaration malformed
85	            } else if (c == ';') {
86	                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0) {
87	                    // the ';' is content of a function that closes later (e.g. an unquoted data: URL); keep scanning
88	                    i++;
89	                    continue;
90	                }
91	                // otherwise end here; a function that never closes only invalidates this declaration
92	                appendSafeDeclaration(value, segStart, i, segmentBad || parenDepth != 0, out);
93	                segStart = i + 1;
94	                segmentBad = false;
95	                parenDepth = 0;
96	            }
97	            i++;
98	        }
99	        if (segStart < length) appendSafeDeclaration(value, segStart, length, segmentBad || parenDepth != 0, out);
100	
101	        if (out.length() == 0) {
102	            StringUtil.releaseBuilderVoid(out);
103	            return null;
104	        }
105	        return StringUtil.releaseBuilder(out);
106	    }
107	
108	    /**
109	     Computes the matching parenthesis of every balanced {@code (} and {@code )} in the value, applying the same
110	     * lexical rules (escapes, quoted strings with bad-string recovery, and comments) as the declaration walk. An
111	     * unmatched parenthesis maps to {@code -1}; a single linear pass keeps style cleaning O(n) even when a value
112	     * contains many semicolons nested in functions.
113	     */
114	    private int[] parenMatches(String value) {
115	        int length = value.length();
116	        int[] match = new int[length];
117	        Arrays.fill(match, -1);
118	        int[] stack = new int[length];
119	        int depth = 0;
120	        int i = 0;
121	        while (i < length) {
122	            char c = value.charAt(i);
123	            if (c == '\\') { i += 2; continue; }
124	            if (c == '"' || c == '\'') {
125	                int[] quote = scanQuoted(value, i + 1, c);
126	                i = quote[1] == 0 ? quote[0] : quote[0] + 1; // at the recovered ';', or past the quote/newline
127	                continue;
128	            }
129	            if (c == '/' && i + 1 < length && value.charAt(i + 1) == '*') {
130	                int close = value.indexOf("*/", i + 2);
131	                if (close < 0) break;
132	                i = close + 2;
133	                continue;
134	            }
135	            if (c == '(') {
136	                stack[depth++] = i;
137	            } else if (c == ')') {
138	                if (depth > 0) {
139	                    int open = stack[--depth];
140	                    match[open] = i;
141	                    match[i] = open;
142	                }
143	            }
144	            i++;
145	        }
146	        return match;
147	    }
148	
149	    /**
150	     * <ul>
151	     *   <li>state {@code 1}: the closing quote was found at {@code end};</li>
152	     *   <li>state {@code 2}: the string was recovered at the newline at {@code end} (the CSS bad-string rule; later
153	     *       declarations stay independently parseable);</li>
154	     *   <li>state {@code 0}: neither quote nor newline remains; {@code end} is the index of the first semicolon at
155	     *       or after the opening quote (the malformed declaration is cut there), or the value length when none.</li>
156	     * </ul>
157	     */
158	    private int[] scanQuoted(String value, int from, char quote) {
159	        int length = value.length();
160	        int firstSemi = -1;
161	        for (int i = from; i < length; i++) {
162	            char c = value.charAt(i);
163	            if (c == '\\') { i++; continue; }
164	            if (c == quote) return new int[] {i, 1};
165	            if (c == '\n' || c == '\r') return new int[] {i, 2}; // bad-string recovery at a CSS newline
166	            if (c == ';' && firstSemi < 0) firstSemi = i;
167	        }
168	        return new int[] {firstSemi >= 0 ? firstSemi : length, 0};
169	    }
170	
171	    /**
172	     Validates the declaration at {@code [start, end)} and, when safe, appends its verbatim text to {@code out}.
173	     @param structurallyBad the containing walk already found a malformed construct (a bad-string token)
174	     */
175	    private void appendSafeDeclaration(String value, int start, int end, boolean structurallyBad, StringBuilder out) {
176	        if (structurallyBad) return;
177	        int p = skipSpaceAndComments(value, start, end);
178	        int q = end;
179	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
180	        if (p == q) return; // whitespace-only fragment, e.g. from a duplicated ';'
181	        int nameStart = p;
182	
183	        // an at-rule in a declaration position: only @import is meaningful inline, and its reference must pass
184	        if (value.charAt(p) == '@') {
185	            if (isSafeImportDeclaration(value, p, q)) append(out, value, start, q);
186	            return;
187	        }
188	        // property: a plain CSS identifier (including a vendor prefix such as -webkit-*) or a custom property
189	        // (--name). Escapes, comments, and quotes are not accepted in a declaration name.
190	        boolean custom = false;
191	        if (value.charAt(p) == '-') {
192	            if (p + 1 < end && value.charAt(p + 1) == '-') {
193	                p += 2;
194	                custom = true;
195	                if (p >= q || !isIdentChar(value.charAt(p))) return; // "--" alone is not a property name
196	                while (p < q && isIdentChar(value.charAt(p))) p++;
197	            } else {
198	                if (p + 1 >= q || !isIdentStart(value.charAt(p + 1))) return; // a bare '-' is not a property name
199	                p++; // let the ordinary identifier run consume the vendor-prefixed remainder
200	            }
201	        }
202	        if (!custom) {
203	            if (p >= q || !isIdentStart(value.charAt(p))) return; // no property name
204	            do { p++; } while (p < q && isIdentChar(value.charAt(p)));
205	        }
206	        p = skipSpaceAndComments(value, p, q); // whitespace/comments may sit between the name and the ':'
207	        if (p >= q || value.charAt(p) != ':') return; // no ':' (empty fragment, junk, duplicate ';')
208	        p++; // step past ':'
209	
210	        if (isDangerousProperty(value, nameStart, p - 1)) return; // known script-entry properties, regardless of value
211	        boolean safe = referencesAreSafe(value, p, q);
212	        if (safe && custom) // a custom property holds arbitrary free text, so scan its whole value as one string
213	            safe = freeTextIsSafe(value.substring(p, q));
214	        if (safe) append(out, value, start, q);
215	    }
216	
217	    /** Appends a surviving declaration, separated from any earlier ones by a single semicolon. */
218	    private void append(StringBuilder out, String value, int from, int to) {
219	        if (out.length() > 0) out.append(';');
220	        out.append(value, from, to);
221	    }
222	
223	    /**
224	     Validates an entire {@code @import} declaration: its leading reference (a quoted URL or a {@code url(...)}) must
225	     * pass the URL rules, and any trailing layer/media/supports conditions must themselves contain no unsafe
226	     * reference.
227	     */
228	    private boolean isSafeImportDeclaration(String value, int at, int end) {
229	        int i = at + 1;
230	        if (!matchesName(value, i, end, "import")) return false;
231	        i += 6;
232	        while (i < end && isCssSpace(value.charAt(i))) i++;
233	        if (i == end) return false;
234	        int afterRef;
235	        char c = value.charAt(i);
236	        if (c == '"' || c == '\'') {
237	            int[] quote = scanQuoted(value, i + 1, c);
238	            if (quote[1] != 1) return false;
239	            if (!safelist.isSafeStyleUrl(tagName, el, unescape(value.substring(i + 1, quote[0])))) return false;
240	            afterRef = quote[0] + 1;
241	        } else if (matchesName(value, i, end, "url")) {
242	            int k = skipSeparators(value, i + 3, end);
243	            if (k >= end || value.charAt(k) != '(') return false;
244	            int argEnd = matchingParen(value, k + 1, end);
245	            if (argEnd < 0 || !isSafeUrlArgument(value, k + 1, argEnd)) return false;
246	            afterRef = argEnd + 1;
247	        } else {
248	            return false;
249	        }
250	        return referencesAreSafe(value, afterRef, end);
251	    }
252	
253	    /** Advances past CSS whitespace and complete block comments; an unterminated comment runs to {@code end}. */
254	    private int skipSpaceAndComments(String value, int i, int end) {
255	        while (i < end) {
256	            char c = value.charAt(i);
257	            if (isCssSpace(c)) { i++; continue; }
258	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
259	                int close = value.indexOf("*/", i + 2);
260	                if (close < 0) return end;
261	                i = close + 2;
262	                continue;
263	            }
264	            break;
265	        }
266	        return i;
267	    }
268	
269	    /** Whitespace and comments may separate a function name from its opening parenthesis ({@code url/**\/( ... )}). */
270	    private int skipSeparators(String value, int i, int end) {
271	        return skipSpaceAndComments(value, i, end);
272	    }
273	
274	    /**
275	     Denies the legacy script-entry properties that load executable or behavior-bound content even through an
276	     * otherwise allowed-looking {@code url(...)}: {@code -moz-binding} (XBL) and IE's {@code behavior}.
277	     */
278	    private boolean isDangerousProperty(String value, int from, int colon) {
279	        int p = from;
280	        while (p < colon && isCssSpace(value.charAt(p))) p++;
281	        int q = colon;
282	        while (q > p && isCssSpace(value.charAt(q - 1))) q--;
283	        String name = value.substring(p, q);
284	        return name.equalsIgnoreCase("-moz-binding") || name.equalsIgnoreCase("behavior");
285	    }
286	
287	    /**
288	     Walks a declaration value in a single lexical pass: strings, comments, escapes, and balanced functions are
289	     recognized exactly as in declaration splitting. Block comments are skipped entirely (their text is never parsed
290	     as CSS); string contents are still scanned for a concealed {@code url(...)}-shaped reference, because when the
291	     string is itself the argument of {@code url()} the browser unescapes it before fetching; every {@code url(...)}
292	     argument, an {@code @import} reference, and the legacy {@code expression(...)} function is normalized and checked
293	     against the safelist. Unbalanced parentheses, an unterminated string or comment, or any failed reference check
294	     rejects the declaration.
295	     */
296	    private boolean referencesAreSafe(String value, int start, int end) {
297	        int parenDepth = 0;
298	        int i = start;
299	        while (i < end) {
300	            char c = value.charAt(i);
301	            if (c == '\\') { i += 2; continue; }
302	            if (c == '"' || c == '\'') {
303	                int[] quote = scanQuoted(value, i + 1, c);
304	                if (quote[1] != 1) return false; // no bad-string recovery inside a value being checked
305	                if (!freeTextIsSafe(value.substring(i + 1, quote[0]))) return false;
306	                i = quote[0] + 1;
307	                continue;
308	            }
309	            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
310	                int close = value.indexOf("*/", i + 2);
311	                if (close < 0 || close >= end) return false; // unterminated comment within the declaration
312	                // comment text is never a declaration, but a reference concealed in a comment must still pass the
313	                // same URL rules so that a rejected URL can never survive in the emitted attribute
314	                if (!freeTextIsSafe(value.substring(i + 2, close))) return false;
315	                i = close + 2;
316	                continue;
317	            }
318	            if (c == '(') { parenDepth++; i++; continue; }
319	            if (c == ')') {
320	                if (parenDepth == 0) return false; // unmatched ')'
321	                parenDepth--;
322	                i++;
323	                continue;
324	            }
325	            if (c == '@') return false; // no at-rule (e.g. a buried @import) is valid inside a declaration value
326	            if (c == ':' && parenDepth == 0)
327	                return false; // a bare ':' outside strings and functions (e.g. a recovered "javascript:" run) is invalid
328	            if (isIdentStart(c) || c == '-') {
329	                int[] name = readName(value, i, end);
330	                int nameEnd = name[0];
331	                String fnName = name[1] == 1 ? unescape(value.substring(i, nameEnd)) : value.substring(i, nameEnd);
332	                int j = skipSeparators(value, nameEnd, end);
333	                if (j < end && value.charAt(j) == '(') {
334	                    int argEnd = matchingParen(value, j + 1, end);
335	                    if (argEnd < 0) return false;
336	                    // a function name whose escapes decode to punctuation (e.g. "l\;expression") is not a real CSS
337	                    // function token; reject rather than risk it being read as two tokens by a quirky engine
338	                    if (!isPlainName(fnName)) return false;
339	                    if (fnName.equalsIgnoreCase("expression")) return false; // legacy JScript entry point
340	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(value, j + 1, argEnd)) return false;
341	                    i = j; // resume at '(' so a nested url()/expression() inside the arguments is also checked
342	                    continue;
343	                }
344	                i = nameEnd;
345	                continue;
346	            }
347	            i++;
348	        }
349	        return parenDepth == 0;
350	    }
351	
352	    /** Tests that a function name is a plain identifier, with no escape that decoded to punctuation or whitespace. */
353	    private static boolean isPlainName(String name) {
354	        int length = name.length();
355	        if (length == 0) return false;
356	        for (int k = 0; k < length; k++) {
357	            char c = name.charAt(k);
358	            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
359	                || (c >= '0' && c <= '9') || c == '-' || c == '_';
360	            if (!ok) return false;
361	        }
362	        return true;
363	    }
364	
365	    /**
366	     Reads a CSS name token (identifier characters, plus backslash escapes) from {@code from}. Returns
367	     {@code [end, escaped]}: {@code end} is the index after the token, and {@code escaped} is 1 when it contained a
368	     backslash. A leading run of dashes is consumed so that e.g. {@code -moz-binding} reads as one token.
369	     */
370	    private int[] readName(String value, int from, int end) {
371	        int i = from;
372	        int escaped = 0;
373	        while (i < end) {
374	            char c = value.charAt(i);
375	            if (c == '\\') {
376	                if (i + 1 >= end) break;
377	                escaped = 1;
378	                i += 2;
379	                continue;
380	            }
381	            if (isIdentChar(c)) { i++; continue; }
382	            break;
383	        }
384	        return new int[] {i, escaped};
385	    }
386	
387	    /**
388	     Applies the same URL rules to text that is not itself parsed as declarations — the body of a quoted string, a
389	     * block comment, or the value of a custom property. Such text cannot introduce a declaration, but a rejected
390	     * reference must not survive in the emitted style, so every {@code url(...)}-shaped reference and every
391	     * {@code @import} reference is extracted (CSS-escapes normalized) and checked; the legacy
392	     * {@code expression(...)} function is always rejected.
393	     */
394	    private boolean freeTextIsSafe(String text) {
395	        int end = text.length();
396	        int i = 0;
397	        while (i < end) {
398	            char c = text.charAt(i);
399	            if (c == '\\') { i += 2; continue; }
400	            if (c == '@' && matchesName(text, i + 1, end, "import")) {
401	                if (!freeTextImportIsSafe(text, i + 7, end)) return false;
402	                i += 7;
403	                continue;
404	            }
405	            if (isIdentStart(c) || c == '-') {
406	                int[] name = readName(text, i, end);
407	                int j = skipSeparators(text, name[0], end);
408	                if (j < end && text.charAt(j) == '(') {
409	                    String fnName = name[1] == 1 ? unescape(text.substring(i, name[0])) : text.substring(i, name[0]);
410	                    int argEnd = matchingParen(text, j + 1, end);
411	                    if (argEnd < 0) return false;
412	                    if (!isPlainName(fnName)) return false;
413	                    if (fnName.equalsIgnoreCase("expression")) return false;
414	                    if (fnName.equalsIgnoreCase("url") && !isSafeUrlArgument(text, j + 1, argEnd)) return false;
415	                    i = j; // resume at '(' so a nested url()/expression() in the arguments is also checked
416	                    continue;
417	                }
418	                i = name[0];
419	                continue;
420	            }
421	            i++;
422	        }
423	        return true;
424	    }
425	
426	    /** Checks the quoted-string or {@code url(...)} reference of an {@code @import} found in free text. */
427	    private boolean freeTextImportIsSafe(String text, int from, int end) {
428	        int i = from;
429	        while (i < end && isCssSpace(text.charAt(i))) i++;
430	        if (i >= end) return true; // a dangling "@import" with no reference is inert junk
431	        char c = text.charAt(i);
432	        if (c == '"' || c == '\'') {
433	            int[] quote = scanQuoted(text, i + 1, c);
434	            if (quote[1] != 1) return false;
435	            return safelist.isSafeStyleUrl(tagName, el, unescape(text.substring(i + 1, quote[0])));
436	        }
437	        if (matchesName(text, i, end, "url")) {
438	            int k = skipSeparators(text, i + 3, end);
439	            if (k >= end || text.charAt(k) != '(') return false;
440	            int argEnd = matchingParen(text, k + 1, end);
441	            return argEnd >= 0 && isSafeUrlArgument(text, k + 1, argEnd);
442	        }
443	        return false;
444	    }
445	
446	    /** Extracts and validates the single URL argument of a {@code url(...)} function. */
447	    private boolean isSafeUrlArgument(String value, int from, int end) {
448	        int i = from;
449	        while (i < end && isCssSpace(value.charAt(i))) i++;
450	        int j = end;
451	        while (j > i && isCssSpace(value.charAt(j - 1))) j--;
452	        if (i == j) return false; // url() with no reference
453	
454	        char first = value.charAt(i);
455	        String raw;
456	        if (first == '"' || first == '\'') {
457	            int[] quote = scanQuoted(value, i + 1, first);
458	            if (quote[1] != 1 || quote[0] + 1 != j) return false; // unterminated or trailing junk inside the quotes
459	            raw = value.substring(i + 1, quote[0]);
460	            for (int k = 0; k < raw.length(); k++) { // the closing quote may not appear inside, escaped or not
461	                char c = raw.charAt(k);
462	                if (c == '\\') { k++; continue; }
463	                if (c == first) return false;
464	            }
465	        } else {
466	            // an unquoted URL token is a single run: bare whitespace or quotes are syntax errors, not part of the URL
467	            for (int k = i; k < j; k++) {
468	                char c = value.charAt(k);
469	                if (c == '\\') { k++; continue; }
470	                if (c == '"' || c == '\'' || isCssSpace(c)) return false;
471	            }
472	            raw = value.substring(i, j);
473	        }
474	        return safelist.isSafeStyleUrl(tagName, el, unescape(raw));
475	    }
476	
477	    /** Returns the index of the ')' matching the '(' whose argument starts at {@code from}, or {@code -1}. */
478	    private int matchingParen(String value, int from, int end) {
479	        int depth = 1;
480	        int i = from;
481	        while (i < end) {
482	            char c = value.charAt(i);
483	            if (c == '\\') { i += 2; continue; }
484	            if (c == '"' || c == '\'') {
485	                int[] quote = scanQuoted(value, i + 1, c);
486	                if (quote[1] != 1) return -1;
487	                i = quote[0] + 1;
488	                continue;
489	            }
490	            if (c == '(') depth++;
491	            else if (c == ')') { depth--; if (depth == 0) return i; }
492	            i++;
493	        }
494	        return -1;
495	    }
496	
497	    private boolean matchesName(String value, int from, int end, String name) {
498	        int len = name.length();
499	        if (from + len > end) return false;
500	        for (int k = 0; k < len; k++) {
501	            char a = value.charAt(from + k);
502	            char b = name.charAt(k);
503	            if (a != b && a != Character.toUpperCase(b)) return false;
504	        }
505	        return true;
506	    }
507	
508	    /**
509	     Decodes CSS backslash escapes in a URL token, mirroring how a browser reads the reference: a {@code \}{@code hEX}
510	     run (up to six hex digits, optionally followed by one whitespace delimiter) becomes its code point, and any other
511	     backslash-prefixed character collapses to that character. An obfuscated scheme such as {@code java\73cript:} or
512	     {@code \6a avascript:} therefore cannot hide from the protocol check. A NUL code point is dropped, matching the
513	     CSS requirement to replace it.
514	     */
515	    static String unescape(String value) {
516	        if (value.indexOf('\\') == -1) return value;
517	        int length = value.length();
518	        StringBuilder sb = null;
519	        int i = 0;
520	        while (i < length) {
521	            char c = value.charAt(i);
522	            if (c == '\\' && i + 1 < length) {
523	                if (sb == null) {
524	                    sb = new StringBuilder(length);
525	                    sb.append(value, 0, i);
526	                }
527	                int h = i + 1;
528	                int hexEnd = h;
529	                while (hexEnd < length && hexEnd - h < 6 && isHex(value.charAt(hexEnd))) hexEnd++;
530	                if (hexEnd > h) {
531	                    int code = Integer.parseInt(value.substring(h, hexEnd), 16);
532	                    if (hexEnd < length && isCssSpace(value.charAt(hexEnd))) hexEnd++;
533	                    // per the CSS spec, NUL, surrogates, and values above the Unicode range become U+FFFD
534	                    if (code == 0 || code > Character.MAX_CODE_POINT
535	                        || (code >= Character.MIN_SURROGATE && code <= Character.MAX_SURROGATE))
536	                        code = 0xFFFD;
537	                    sb.appendCodePoint(code);
538	                    i = hexEnd;
539	                } else {
540	                    sb.append(value.charAt(i + 1));
541	                    i += 2;
542	                }
543	                continue;
544	            }
545	            if (sb != null) sb.append(c);
546	            i++;
547	        }
548	        return sb != null ? sb.toString() : value;
549	    }
550	
551	    private static boolean isCssSpace(char c) {
552	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
553	    }
554	
555	    private static boolean isHex(char c) {
556	        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
557	    }
558	
